}

func newGrantOrgAddCmd() *cobra.Command {
	var provider, providerUserID, role string
	cmd := &cobra.Command{
		Use:   "add <org>",
		Short: "Add a member to an org",
		Args:  cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
